import sys

def first_index(s):
    res = []
    for ch in s:
        if ch not in res:
            res.append(ch)
    return [s.find(ch) for ch in res]

def is_isomorphic_brute(s, t):
    return first_index(s) == first_index(t)

if __name__ == '__main__':
    data = sys.stdin.read().splitlines()
    if len(data) < 2:
        sys.exit(0)
    print('true' if is_isomorphic_brute(data[0], data[1]) else 'false')

import sys

def is_isomorphic_opt(s, t):
    if len(s) != len(t):
        return False
    s2t, t2s = {}, {}
    for a, b in zip(s, t):
        if a in s2t and s2t[a] != b:
            return False
        if b in t2s and t2s[b] != a:
            return False
        s2t[a] = b
        t2s[b] = a
    return True

if __name__ == '__main__':
    data = sys.stdin.read().splitlines()
    if len(data) < 2:
        sys.exit(0)
    print('true' if is_isomorphic_opt(data[0], data[1]) else 'false')

import sys

def encode(s):
    seen, out = {}, []
    for i, ch in enumerate(s):
        if ch not in seen:
            seen[ch] = i
        out.append(seen[ch])
    return out

def is_isomorphic_best(s, t):
    return encode(s) == encode(t)

if __name__ == '__main__':
    data = sys.stdin.read().splitlines()
    if len(data) < 2:
        sys.exit(0)
    print('true' if is_isomorphic_best(data[0], data[1]) else 'false')
